// This code has been partially generated by an AI.
import { expect, test } from '@playwright/test';

test.describe('Suite conversion pages', () => {
  test.use({
    viewport: { width: 390, height: 844 },
    contextOptions: { reducedMotion: 'reduce' },
  });

  test('guides visitors with the light green brand and three clear paths', async ({
    page,
  }) => {
    await page.goto('/');

    await expect(page.locator('html')).toHaveAttribute('data-theme', 'light');
    await expect(page.locator('[data-appearance-theme]')).toHaveCount(0);
    await expect(
      page.getByRole('heading', {
        level: 1,
        name: /Weniger Reibung.*Mehr Wirkung aus Ihrer IT/,
      }),
    ).toBeVisible();
    await expect(
      page.getByRole('link', { name: 'Services entdecken' }),
    ).toBeVisible();
    await expect(page.getByRole('link', { name: 'Suite entdecken' })).toBeVisible();
    await expect(page.getByRole('link', { name: 'semrel entdecken' })).toBeVisible();
    await expect(
      page.getByRole('heading', { name: 'Gute Lösungen beginnen mit Klarheit.' }),
    ).toBeVisible();
    await expect(page.locator('#roi-rechner')).toHaveCount(0);
    await expect(page.getByText(/1\.000%|10x|90\+ Score/)).toHaveCount(0);

    const palette = await page.locator('html').evaluate((element) => {
      const style = getComputedStyle(element);
      return {
        brand: style.getPropertyValue('--color-meg-brand').trim(),
        accent: style.getPropertyValue('--color-meg-accent').trim(),
      };
    });
    expect(palette).toEqual({ brand: '#dfece0', accent: '#366544' });
  });

  test('loads analytics only after explicit consent', async ({ page }) => {
    await page.addInitScript(() => {
      localStorage.removeItem('waldheim-cookie-consent-v1');
    });
    await page.goto('/');

    await expect(page.locator('#waldheim-cookie-banner')).toBeVisible();
    await expect(page.locator('#waldheim-ga4-script')).toHaveCount(0);

    await page.getByRole('button', { name: 'Alle akzeptieren' }).click();
    await expect(page.locator('#waldheim-ga4-script')).toHaveCount(1);
    await expect(page.locator('#waldheim-cookie-banner')).toBeHidden();
  });

  test('keeps analytics disabled when only necessary storage is accepted', async ({
    page,
  }) => {
    await page.addInitScript(() => {
      localStorage.removeItem('waldheim-cookie-consent-v1');
    });
    await page.goto('/');

    await page.getByRole('button', { name: 'Nur notwendige' }).click();

    await expect(page.locator('#waldheim-ga4-script')).toHaveCount(0);
    await expect(page.locator('#waldheim-cookie-banner')).toBeHidden();
  });

  test('presents clear demo, trial, and pricing paths with list-price calculation', async ({
    page,
  }) => {
    await page.goto('/suite/');

    await expect(
      page.getByRole('heading', {
        level: 1,
        name: 'ERP und CRM, die Ihre Abläufe verbinden.',
      }),
    ).toBeVisible();

    const demoLink = page.locator('[data-track-event="cta_suite_demo"]');
    await expect(demoLink).toHaveAttribute('href', '/kontakt/');
    await expect(demoLink).toBeInViewport();

    const trialLink = page.locator('[data-track-event="cta_suite_trial"]');
    await expect(trialLink).toHaveAttribute(
      'href',
      'https://suite.waldheim.dev',
    );
    await expect(
      page.locator('[data-testid="latest-blog-banner"]'),
    ).toHaveCount(0);
    await expect(page.locator('nav').getByText(/· Live/)).toHaveCount(0);
    await expect(page.locator('#calc-discount')).toHaveCount(0);
    await expect(page.locator('#calc-units')).toHaveCount(0);
    await expect(page.getByText('40% Rabatt im ersten Jahr')).toHaveCount(0);
    await expect(page.locator('#calc-total')).toHaveText('€145');

    await page.locator('#calc-seats').evaluate((element) => {
      const input = element as HTMLInputElement;
      input.value = '10';
      input.dispatchEvent(new Event('input', { bubbles: true }));
    });
    await expect(page.locator('#calc-total')).toHaveText('€290');

    await page.locator('#calc-tier-enterprise').click();
    await expect(page.locator('#calc-total')).toHaveText('€89');
  });

  test('does not present invented customer metrics on the contact page', async ({
    page,
  }) => {
    await page.goto('/kontakt/');

    await expect(page.getByText('98%', { exact: true })).toHaveCount(0);
    await expect(page.getByText('< 4h', { exact: true })).toHaveCount(0);
    await expect(page.getByText('100%', { exact: true })).toHaveCount(0);
    await expect(page.getByText('30 Minuten', { exact: false })).toBeVisible();
    await expect(page.getByText('24h-SLA', { exact: false })).toHaveCount(0);
  });

  test('colors the privacy switch when enabled', async ({ page }) => {
    await page.goto('/kontakt/');

    const privacySwitch = page.getByRole('switch', {
      name: 'Datenschutzbestimmung',
    });
    const track = page.locator('#privacy + span');
    await track.click();
    await expect(privacySwitch).toBeChecked();
    await expect(track).toHaveCSS(
      'background-color',
      'rgb(54, 101, 68)',
    );
  });

  test('does not advertise an unconfigured early-adopter discount', async ({
    page,
  }) => {
    await page.goto('/suite/preise/');

    await expect(page.getByText(/40\s?% Rabatt/i)).toHaveCount(0);
    await expect(
      page.getByText(/0,30 EUR|1,00 EUR|ab €8|ab €15|ab €25/i),
    ).toHaveCount(0);
    await expect(
      page.getByText('Preis laut', { exact: false }).first(),
    ).toBeVisible();
    const legalLinks = page
      .locator('nav[aria-label="Rechtliche Informationen zum Angebot"]')
      .first();
    await expect(legalLinks.getByRole('link', { name: 'AGB' })).toHaveAttribute(
      'href',
      '/agb/',
    );
    await expect(
      legalLinks.getByRole('link', { name: 'Widerrufsbelehrung' }),
    ).toHaveAttribute('href', '/widerrufsbelehrung/');
  });
});
